// ── Custom iterable: NumberRange ────────────────────────────────
class NumberRange {
  constructor(start, end) {
    this.start = start;
    this.end   = end;
  }

  // Implement the iterable protocol
  [Symbol.iterator]() {
    let current = this.start;
    const end   = this.end;
    return {
      next() {
        if (current <= end) return { value: current++, done: false };
        return { value: undefined, done: true };
      }
    };
  }
}

const range = new NumberRange(1, 5);
for (const n of range) process.stdout.write(n + ' '); // 1 2 3 4 5
console.log();
console.log([...range]); // [1, 2, 3, 4, 5]  — spread works!

// ── Generator: lazy infinite Fibonacci ──────────────────────────
function* fibonacci() {
  let [a, b] = [0, 1];
  while (true) {
    yield a;
    [a, b] = [b, a + b];
  }
}

function take(n, iterable) {
  const result = [];
  for (const val of iterable) {
    result.push(val);
    if (result.length >= n) break;
  }
  return result;
}

console.log(take(8, fibonacci())); // [0,1,1,2,3,5,8,13]

// ── Generator pipeline: lazy map + filter (no intermediate arrays)
function* mapGen(iter, fn) {
  for (const val of iter) yield fn(val);
}
function* filterGen(iter, pred) {
  for (const val of iter) { if (pred(val)) yield val; }
}

const evens = filterGen(mapGen(fibonacci(), x => x * 2), x => x < 50);
console.log([...evens]); // [0,2,2,4,6,10,16,26,42] — even fibonacci*2 < 50

// ── String is iterable — character iteration ────────────────────
const chars = [...'hello'];
console.log(chars); // ['h','e','l','l','o']

// ── Manual Iterator skeleton ──────────────────────────────────────
const myIterator = {
  data:  ['a', 'b', 'c'],
  index: 0,
  next() {
    if (this.index < this.data.length)
      return { value: this.data[this.index++], done: false };
    return { value: undefined, done: true };
  },
  [Symbol.iterator]() { return this; } // self-referential — also an Iterable
};

for (const ch of myIterator) process.stdout.write(ch + ' '); // a b c
console.log();

// ── Generator skeleton ────────────────────────────────────────────
function* range(start, end, step = 1) {
  for (let i = start; i <= end; i += step) yield i;
}

console.log([...range(0, 10, 2)]); // [0,2,4,6,8,10]

// ── Async iterator (paginated API) ───────────────────────────────
async function* paginatedFetch(url) {
  let page = 1;
  while (true) {
    const res  = await fetch(`${url}?page=${page}`);
    const data = await res.json();
    if (!data.items.length) return;
    yield* data.items;   // yield each item individually
    if (!data.hasMore) return;
    page++;
  }
}
// Usage: for await (const item of paginatedFetch('/api/products')) { ... }
